def parse_cookies(header):
    cookies = {}
    if not header:
        return cookies
    for part in header.split(';'):
        if '=' not in part:
            continue
        key, _, value = part.partition('=')
        key = key.strip()
        if key:
            cookies[key] = value.strip()
    return cookies

