    def add(self, product):
        self._items[product.sku] = product

    def get(self, sku):
        if sku not in self._items:
            raise KeyError(sku)
        return self._items[sku]

    def in_stock(self, sku, qty):
        return sku in self._items and self._items[sku].stock >= qty

