import math


def round_half_up(value):
    return int(math.floor(value + 0.5))


def bulk_discount_rate(qty):
    if qty >= 10:
        return 0.10
    if qty >= 5:
        return 0.05
    return 0.0


def apply_tax(subtotal_cents, tax_rate):
    return subtotal_cents + round_half_up(subtotal_cents * tax_rate)

