from .pricing import apply_tax, bulk_discount_rate, round_half_up


class Cart:
    def __init__(self, catalog):
        self.catalog = catalog
        self._lines = {}

    def add(self, sku, qty=1):
        if qty <= 0:
            raise ValueError('qty must be positive')
        product = self.catalog.get(sku)
        new_qty = self._lines.get(sku, 0) + qty
        if product.stock < new_qty:
            raise ValueError('insufficient stock')
        self._lines[sku] = new_qty

    def set_qty(self, sku, qty):
        if qty < 0:
            raise ValueError('qty must be non-negative')
        if qty == 0:
            self._lines.pop(sku, None)
            return
        product = self.catalog.get(sku)
        if product.stock < qty:
            raise ValueError('insufficient stock')
        self._lines[sku] = qty

    def remove(self, sku):
        self._lines.pop(sku, None)

    def subtotal_cents(self):
        total = 0
        for sku, qty in self._lines.items():
            line = self.catalog.get(sku).price_cents * qty
            line -= round_half_up(line * bulk_discount_rate(qty))
            total += line
        return total

    def total_cents(self, tax_rate, coupon=None, today=None):
        subtotal = self.subtotal_cents()
        if coupon is not None and today is not None and coupon.is_valid(subtotal, today):
            subtotal -= round_half_up(subtotal * coupon.percent)
        return apply_tax(subtotal, tax_rate)
